import Canvas2D from '../base/Canvas2D';
import random from '../utils/random';
import Particle from '../utils/Particle';
import Vector from '../utils/Vector';
import { distance } from '../utils/math';
import gsap from 'gsap';

// tweakable params
const PARAMS = {
  k: 0.005,
  numParticles: 1000,
  mouseRadius: 100,
};

const TWO_PI = Math.PI * 2;

// uncomment to create a noise instance
// const rand = random();

export default class Experiment3 extends Canvas2D {
  constructor(options) {
    super(options);

    this.description = `
      <p>Description of experiment</p>
      <p>Press Shift + D to bring up the debug panel.</p>
    `;

    this.pane.addInput(PARAMS, 'k', { min: 0, max: 0.1 });
    this.pane.addInput(PARAMS, 'numParticles', { min: 0, max: 3000 });
    this.pane.addInput(PARAMS, 'mouseRadius', { min: 0, max: 500 });
    this.pane
      .addButton({
        title: 'Generate',
      })
      .on('click', () => {
        this.generate();
      });

    this.generate();
    this.start();
  }

  generate() {
    this.springs = [];
    this.mouseRadius = PARAMS.mouseRadius;
    const goldenAngle = TWO_PI / ((1 + Math.sqrt(5)) / 2);
    let angle, x, y, radius;
    let count = PARAMS.numParticles;

    for (let i = 0; i < count; i++) {
      angle = i * goldenAngle;
      radius = (Math.sqrt(i / count) * Math.min(this.width, this.height)) / 2.8;

      x = this.centerX + Math.cos(angle) * radius;
      y = this.centerY + Math.sin(angle) * radius;

      const position = new Vector(x, y);
      const springPoint = new Vector(x, y);

      const distCenter = position.distanceTo(
        new Vector(this.centerX, this.centerY)
      );
      const radius = 1.5 + Math.sin(distCenter / 20) + 1;

      this.springs.push({
        springPoint,
        particle: new Particle({
          position,
          radius,
          friction: 0.9,
        }),
      });
    }
  }

  onMousePress() {
    const mouseRadius = PARAMS.mouseRadius * 2;
    gsap.to(PARAMS, { duration: 0.3, mouseRadius });
  }

  onMouseRelease() {
    gsap.to(PARAMS, { duration: 0.3, mouseRadius: this.mouseRadius });
  }

  update(dt, time) {
    this.ctx.clearRect(0, 0, this.width, this.height);
    this.ctx.fillStyle = '#081A40';

    for (let spring of this.springs) {
      const springDist = spring.springPoint.subtract(spring.particle.position);
      const springForce = springDist.multiplyBy(PARAMS.k);
      spring.particle.velocity.addTo(springForce);

      const distCenter = spring.springPoint.distanceTo(
        new Vector(this.centerX, this.centerY)
      );
      const radius = 1.2 + Math.sin(distCenter / 30 + time * 3) + 1.3;

      spring.particle.radius = radius;
      spring.particle.update();
      spring.particle.draw(this.ctx);

      // mouse force
      const mouseVec = new Vector(this.mousePos[0], this.mousePos[1]);
      const relativePos = spring.particle.position.subtract(mouseVec);
      const mouseDist = distance(spring.particle.position, mouseVec);
      const forceDir = relativePos.divideBy(mouseDist);

      const mouseForce = (PARAMS.mouseRadius - mouseDist) / PARAMS.mouseRadius;

      if (mouseForce < 0) mouseForce = 0;

      // apply mouse force
      const mouseVel = forceDir.multiplyBy(mouseForce * 25);
      spring.particle.velocity.addTo(mouseVel);
    }

    if (!this.mouseDown) {
      this.mousePos = [-10000, -10000];
    }
  }
}
