import Vector from './Vector';
import { distance } from './math';

export default class Particle {
  constructor({
    position,
    velocity,
    gravity,
    speed = 0,
    direction = 0,
    mass = 1,
    radius = 0,
    friction = 1,
    bounce = -1,
  }) {
    // settings
    this.mass = mass;
    this.radius = radius;
    this.bounce = bounce;
    this.friction = friction;

    this.position = position || new Vector();
    this.velocity = velocity || new Vector();
    this.gravity = gravity || new Vector();

    this.velocity.setLength(speed);
    this.velocity.setAngle(direction);
  }

  accelerate(acc) {
    this.velocity.addTo(acc);
  }

  update() {
    this.velocity.multiplyScalar(this.friction);
    this.velocity.addTo(this.gravity);
    this.position.addTo(this.velocity);
  }

  angleTo(p2) {
    return Math.atan2(
      p2.position.y - this.position.y,
      p2.position.x - this.position.x
    );
  }

  distanceTo(p2) {
    return distance(this.position, p2.position);
  }

  gravitateTo(p2) {
    const grav = new Vector();
    const dist = this.distanceTo(p2);
    grav.setLength(p2.mass / (dist * dist));
    grav.setAngle(this.angleTo(p2));
    this.velocity.addTo(grav);
  }

  draw(ctx) {
    ctx.beginPath();
    ctx.arc(
      this.position.x,
      this.position.y,
      this.radius,
      0,
      Math.PI * 2,
      false
    );
    ctx.fill();
  }
}
