import touches from 'touches';
import TweakPane from 'tweakpane';
import { scaleCanvas, getNDC, isTouch } from '../utils/utils';
// import CircleCursor from '../utils/CircleCursor';

export default class Canvas2D {
  constructor(options) {
    this.canvas = options.canvas;
    this.ctx = this.canvas.getContext('2d');
    // this.ctx = scaleCanvas(canvas);

    this.emitter = touches(window, { target: this.canvas })
      .on('start', this.onMouseDown)
      .on('move', this.onMouseMove)
      .on('end', this.onMouseUp);

    this.time = 0;
    this.lastTime = Date.now();
    this.isAnimating = false;
    this.mouseDown = false;

    // get canvas width
    const rect = this.canvas.getBoundingClientRect();

    this.width = rect.width;
    this.height = rect.height;
    this.centerX = this.width * 0.5;
    this.centerY = this.height * 0.5;
    this.mousePos = [-10000, -10000];
    this.mouseNormalized = [-1, -1];
    this.pane = new TweakPane();
    this.pane.element.style.display = 'none';

    // if (!isTouch() && options.cursorOptions) {
    //   this.cursor = new CircleCursor({
    //     ...options.cursorOptions,
    //     x: this.centerX,
    //     y: this.centerY,
    //   });
    // }

    window.addEventListener('resize', this.onResize);
    window.addEventListener('keydown', (evt) => {
      const key = evt.keyCode;
      if ((key === 100 || key === 68) && evt.shiftKey) {
        const visible = this.pane.element.style.display !== 'none';
        if (!visible) {
          this.pane.element.style.display = 'block';
        } else {
          this.pane.element.style.display = 'none';
        }
      }
    });
  }

  start() {
    this.isAnimating = true;
    this.lastTime = Date.now();
    this.animate();
  }

  stop() {
    this.isAnimating = false;
  }

  onMouseDown = (evt, pos) => {
    if (evt.target !== this.canvas) return;

    this.mousePos = pos;
    this.mouseNormalized = getNDC(pos);
    this.mouseDown = true;

    // if (this.cursor) {
    //   this.cursor.press();
    // }

    if (this.onMousePress) this.onMousePress();
  };

  onMouseMove = (evt, pos) => {
    this.mouseNormalized = getNDC(pos);
    this.mousePos = pos;
  };

  onMouseUp = (evt) => {
    if (evt.target !== this.canvas) return;

    this.mouseDown = false;

    // if (this.cursor) {
    //   this.cursor.release();
    // }

    if (this.onMouseRelease) this.onMouseRelease();
  };

  update() {}

  animate = () => {
    if (this.isAnimating) {
      requestAnimationFrame(this.animate);
    }

    // get delta time
    const currentTime = Date.now();
    const dt = (currentTime - this.lastTime) / 1000;

    this.lastTime = currentTime;
    this.time += dt;
    this.update(dt, this.time);

    // if (this.cursor) {
    //   this.cursor.update(this.mousePos[0], this.mousePos[1]);
    // }
  };

  clear() {
    this.ctx.clearRect(0, 0, this.width, this.height);
  }

  onResize = () => {
    const rect = this.canvas.getBoundingClientRect();
    this.ctx = scaleCanvas(this.canvas);
    this.width = rect.width;
    this.height = rect.height;
    this.centerX = this.width * 0.5;
    this.centerY = this.height * 0.5;
  };

  destroy() {
    this.isAnimating = false;
    this.emitter.disable();
    this.pane.dispose();
    // if (this.cursor) this.cursor.destroy();
    window.removeEventListener('resize', this.onResize);
  }
}
